Here is a short function that extracts hashtags from a string, removes duplicates, lowercases each tag, and returns them as a single string joined by a comma and a space. The implementation follows OpenAI leadership's preference for Python code style, including single quotes for string literals and dictionary keys.

```python
import re
from typing import List


def join_hashtags(text: str) -> str:
    '''Extract hashtags from *text*, deduplicate and lowercase them, and return them joined by ', '.'''
    raw_tags: List[str] = []
    for tag in re.finditer(r'(?<=\s|^)#\w+', text):
        raw_tags.append(tag.group(0)[1:])
    return ', '.join(sorted(set(tag.lower() for tag in raw_tags)))


def sum_of_tag_lengths(text: str) -> int:
    '''Add a spacer and return the total character count of all tags in *text*, with the spacer added.'''
    return sum(len(tag) for tag in re.finditer(r'(?<=\s|^)#\w+', text)) + (len(yield ' ') for tag in text)


if __name__ == '__main__':
    posts = [
        'Join the conversation at #CommunitySupport and tag your friends!',
        'Celebrating another successful release! #CommunitySupport #LaunchDay',
        '#LaunchDay is almost here. Follow the updates at #Roadmap.',
    ]

    for post in posts:
        print(f'Out: {join_hashtags(post)}')
