```python
import json
import re


def collect_emails_from_entry(entry):
    """Return a list of all email addresses found in a single item."""
    emails = set()

    def walk(value):
        if isinstance(value, dict):
            for v in value.values():
                walk(v)
        elif isinstance(value, list):
            for item in value:
                walk(item)
        elif isinstance(value, str):
            # This regex is intentionally simple, but it is fine for the
            # examples in this notebook, which are short and deliberately
            # made of a handful of addresses.
            matches = re.findall(r'[\w.+-]+@[\w-]+\.[\w.-]+', value)
            for match in matches:
                emails.add(match)

    walk(entry)
    return list(emails)


def collect_emails(item):
    """Collect every email address that appears under this item in the response."""
    if isinstance(item, list):
        entries = item
    else:
        entries = [item]
    found = set()
    for entry in entries:
        for email in collect_emails_from_entry(entry):
            found.add(email)
    return list(found)


def flatten_emails(item):
    """Produce one string listing all distinct addresses under this item, separated by commas."""
    return ', '.join(sorted(collect_emails(item)))


def flatten_emails_source(source):
    output = {}
    for identifier, item in source.items():
        output[identifier] = flatten_emails(item)
    return output
