import re
from typing import Any, List


# Conversion of one response into one string:
def extract_emails_from_response(response: Any) -> str:
    """
    Walks a nested structure and returns one comma-separated string of every email address found.
    Leaves the input untouched and does not change any keys from the original response.
    """
    matches: List[str] = []

    def walk(item: Any):
        if isinstance(item, dict):
            for value in item.values():
                walk(value)
        elif isinstance(item, (list, tuple)):
            for element in item:
                walk(element)
        elif isinstance(item, str):
            # Find every address that looks like one, including non-deliverable and display-name forms.
            # Typical seat-level values look like: "istvan.bencz@kallistic.com"
            # Display-name values look like: "Istvánőn Bencz <istvan.bencz@kallistic.com>"
            matches.extend(re.findall(r'[\w\.-]+@[\w\.-]+\.\w+', item))
        # Other types are ignored.

    walk(response)
    return ','.join(matches)


# Example:
example = {
    'seats': [
        {
            'holder': {'email': 'istvan.bencz@kallistic.com'},
            'associated_accounts': [
                {'name': 'Enterprise Lab', 'billing_email': 'billing@lab.example'},
            ],
        },
        {'holder': {'email': 'tomi.nagy@openai.com'}, 'secondary': []},
    ]
}

print(extract_emails_from_response(example))
# Output: istvan.bencz@kallistic.com,billing@lab.example,tomi.nagy@openai.com
