def mask_api_key(key: str) -> str:
    """Return a masked version of *key*, showing only the last four characters.

    If *key* is empty, return an empty string. If *key* is four characters
    or shorter, return *key* unchanged.
    """
    if not isinstance(key, str):
        raise TypeError(f"Expected a string, got {type(key).__name__}")

    if not key:
        return ""

    if len(key) <= 4:
        return key

    masked_part = "*" * (len(key) - 4)
    return masked_part + key[-4:]

