import copy


class StageConfig:
    """Load and return configuration settings for a named deployment stage.

    Parameters:
        default_stage: The stage name used when no explicit stage is supplied.
    """

    CONFIG = {
        "dev": {
            "database_url": "postgresql:///devdb",
            "logging_level": "DEBUG",
            "feature_flags": {"beta_user_dashboard": True},
        },
        "staging": {
            "database_url": "postgresql:///stagingdb",
            "logging_level": "INFO",
            "feature_flags": {"beta_user_dashboard": False},
        },
        "prod": {
            "database_url": "postgresql:///proddb",
            "logging_level": "WARNING",
            "feature_flags": {"beta_user_dashboard": False},
        },
    }

    def __init__(self, default_stage="dev"):
        if default_stage not in self.CONFIG:
            raise ValueError(f"Unknown stage: {default_stage}")
        self.default_stage = default_stage

    def get_settings(self, stage=None):
        """Return a copy of the settings dictionary for the requested stage.

        If ``stage`` is ``None``, the default stage is used.
        A ``ValueError`` is raised if ``stage`` is not among the recognized stage names.
        """
        chosen = stage if stage is not None else self.default_stage
        if chosen not in self.CONFIG:
            raise ValueError(f"Unknown stage: {chosen}")
        return copy.deepcopy(self.CONFIG[chosen])

    def list_available_stages(self):
        """Return the names of stages that have a configuration block."""
        return list(self.CONFIG.keys())
