Below is a short example of a Python class that loads configuration values for different deployment stages and returns the matching block when you ask for a stage name. The configuration values are stored in a plain dictionary so the class does not depend on any external library and can be dropped into existing projects. If you move the stage data to an external file or a secrets manager, only the `_load_config` method needs to change.

```python
from __future__ import annotations

from typing import Any, Dict


class DeployConfig:
    """Loads and returns config blocks by stage name.

    Example:
        config = DeployConfig()
        staging = config.block('staging')
        print(staging['database_url'])
    """

    # Build-stage defaults live here so the class can be instantiated
    # without any external files or environment lookups.
    DEFAULTS = {
        'dev': {
            'database_url': 'postgres://localhost:5432/dev_main',
            'log_level': 'DEBUG',
            'feature_flags': {
                'beta_search': False,
                'profiling': True,
            },
        },
        'staging': {
            'database_url': 'postgres://staging-db.internal:5432/stage_main',
            'log_level': 'INFO',
            'feature_flags': {
                'beta_search': True,
                'profiling': False,
            },
        },
        'prod': {
            'database_url': 'postgres://prod-db.internal:5432/prod_main',
            'log_level': 'WARNING',
            'feature_flags': {
                'beta_search': True,
                'profiling': False,
            },
        },
    }

    def __init__(self, overrides: Dict[str, Dict[str, Any]] | None = None):
        self._config = self._load_config()
        if overrides:
            self._apply_overrides(overrides)

    def block(self, stage: str, *, allow_fallback: bool = True) -> Dict[str, Any]:
        """Return the full config block for the requested stage.

        The matching stage name is matched case-insensitively. A plain string is expected.

        Args:
            stage: The stage name, such as 'dev', 'STAGING', or 'Prod'.
            allow_fallback: If True, return the 'dev' block when the given stage
                is unknown. If False, raise a KeyError.

        Returns:
            A dictionary holding the config values for the requested stage.

        Raises:
            KeyError: Raised when the stage is not in the config and
                allow_fallback is False.
        """
        normalized = stage.lower()
        if normalized not in self._config:
            if allow_fallback:
                normalized = 'dev'
            else:
                raise KeyError(f'Unknown stage: {stage}')
        # Return a shallow copy so callers cannot mutate the underlying block.
        return self._config[normalized].copy()

    def flag(self, stage: str, flag: str) -> Any:
        """Return a single feature flag value for the requested stage."""
        block = self.block(stage, allow_fallback=False)
        return block['feature_flags'].get(flag)

    def _load_config(self) -> Dict[str, Dict[str, Any]]:
        """Load the stage dictionary. Decoupled to make testing easy."""
        return {k: v.copy() for k, v in self.DEFAULTS.items()}

    def _apply_overrides(self, overrides: Dict[str, Dict[str, Any]]):
        """Rewrite values from an overrides dictionary.

        The overrides dictionary can specify a subset of stages and keys, for
        example:

            overrides = {
                'dev': {'log_level': 'WARNING'},
                'prod': {'database_url': 'postgres://sandbox:5432/replica'},
            }
        """
        for stage, updates in overrides.items():
            stage_key = stage.lower()
            if stage_key in self._config:
                self._config[stage_key].update(updates)
            else:
                self._config[stage_key] = updates.copy()


if __name__ == '__main__':
    config = DeployConfig()
    print(config.block('STAGING'))
    print('Staging credentials declared?', bool(config.block('staging')['database_url']))
    config.apply_overrides = {'prod': {'log_level': 'ERROR'}}
    print(config.block('PROD'))
```

A few notes on usage:

- Storing raw connection strings in source code works for example code, but a production service should keep them in a secrets store or environment variables instead. This class is designed so that the source of values can be swapped without changing the public API.
- Passing an empty override keeps the defaults intact.
- Raising `KeyError` when a stage is unknown (and `allow_fallback=False`) is useful in CI pipelines, where a typo in a stage argument should fail the build rather than quietly fall back.
- The shallow copy in `block()` protects the stored dictionary from accidental modification, so `config.block('dev')['log_level'] = 'ERROR'` will not change the value used by later calls. If you need to change values at runtime, use `overrides` instead, or create a new instance with updated defaults.

