import os
from typing import Any, ClassVar, Dict, Optional


class StageNotConfigured(KeyError):
    """Raised when a requested configuration stage is not present in the store."""


class StageConfig:
    """
    Loads and returns configuration blocks for named deployment stages.

    Example:
        config = StageConfig(stage_name="staging")
        print(config.get("database_url", "unset"))
    """

    #: Mapping of stage names to their configuration blocks.
    _STAGE_BLOCKS: ClassVar[Dict[str, Dict[str, Any]]] = {
        "dev": {
            "database_url": "postgresql://dev_user:dev_pass@localhost/devdb",
            "cache_seconds": 10,
            "log_level": "DEBUG",
            "feature_flags": {
                "enable_rollout_safety": False,
                "use_new_scoring_path": False,
            },
        },
        "staging": {
            "database_url": "postgresql://staging_user:staging_pass@staging-db.example/status",
            "cache_seconds": 30,
            "log_level": "INFO",
            "feature_flags": {
                "enable_rollout_safety": True,
                "use_new_scoring_path": False,
            },
        },
        "prod": {
            "database_url": "postgresql://prod_user:PROD_ENCRYPTED_PASS@prod-db.internal/main",
            "cache_seconds": 300,
            "log_level": "WARNING",
            "feature_flags": {
                "enable_rollout_safety": True,
                "use_new_scoring_path": True,
            },
        },
    }

    #: Environment variable used for stage lookup when a caller does not pass one.
    _ENV_STAGE_VAR: ClassVar[str] = "STAGE"

    #: Default stage value used when no argument or environment variable is set.
    _DEFAULT_STAGE: ClassVar[str] = "dev"

    def __init__(self, stage_name: Optional[str] = None):
        """
        Resolve the effective stage and cache its configuration block.

        If ``stage_name`` is None, the loader reads the stage from the
        ``STAGE`` environment variable, and falls back to the hard-coded default.
        The resolved stage must exist in the configuration store, else
        a ``StageNotConfigured`` exception is raised.

        Raises:
            StageNotConfigured: If the resolved stage does not have a mapping.
        """
        candidate = stage_name or os.getenv(self._ENV_STAGE_VAR, "").strip()
        self._stage = candidate or self._DEFAULT_STAGE

        try:
            self._block = self._STAGE_BLOCKS[self._stage]
        except KeyError as exc:
            raise StageNotConfigured(self._stage) from exc

    @classmethod
    def stages_available(cls) -> tuple[str, ...]:
        """Return a tuple of stage names that have a configuration block."""
        return tuple(cls._STAGE_BLOCKS)

    @property
    def stage(self) -> str:
        """The resolved stage used by this instance."""
        return self._stage

    def get(self, key: str, default: Optional[Any] = None) -> Any:
        """
        Return the value for ``key`` inside the current stage block.

        If ``key`` is not present, ``default`` is returned. A shallow copy of the
        block is never exposed through this method; retrieving a sub-dictionary
        returns the original sub-dictionary object, so callers who need an
        isolated copy should use ``copy`` on the returned value.
        """
        return self._block.get(key, default)

    def as_dict(self) -> Dict[str, Any]:
        """
        Return the full configuration block for the resolved stage.

        The returned dictionary is a shallow copy and may be modified without
        affecting other stages. Nested dictionaries share references with the
        original block.
        """
        return self._block.copy()

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}(stage={self._stage!r})"

    def __getitem__(self, key: str) -> Any:
        """
        Allow dict-like lookup, so ``config["log_level"]`` returns a key in the block.
        KeyError is raised for unknown keys.
        """
        return self._block[key]

    def __contains__(self, key: object) -> bool:
        """Return whether the current block defines ``key``."""
        return key in self._block

    def items(self) -> Any:
        """Return an iterator over (key, value) pairs of the current block."""
        return iter(self._block.items())

    # Placeholder for future expansion. Not used by the example below.
    def _load_from_file(self, path: str) -> Dict[str, Any]:
        """
        Load a configuration block from a JSON file.

        The method reads the file, validates that it is a dictionary, and
        returns it. Errors are raised as KeyError for missing files and
        ValueError for malformed contents so that they do not get silently
        swallowed.
        """
        import json

        with open(path, "r", encoding="utf-8") as handle:
            data = json.load(handle)

        if not isinstance(data, dict):
            raise ValueError(f"Configuration file {path} must contain a JSON object.")
        return data


if __name__ == "__main__":
    loader = StageConfig(stage_name=os.getenv("EXAMPLE_STAGE", StageConfig._DEFAULT_STAGE))
    print(loader)
    for key in loader.as_dict():
        print(f"{key}: {loader.get(key)}")
```

