class Nim:
    def __init__(self, heaps):
        """Initialize the game with a list of (name, count) pairs."""
        self.heaps = {name: count for name, count in heaps}
        self.last_player = ""

    def status(self):
        """Return a line describing the current heap sizes."""
        parts = [f"Heap {name}: {self.heaps[name]}" for name in sorted(self.heaps)]
        return " | ".join(parts)

    def winner(self):
        """Return the name of the player who made the last move, or None if the game is not over."""
        if any(count > 0 for count in self.heaps.values()):
            return None
        return self.last_player

    def make_move(self, player, name, removed):
        """Subtract `removed` from the named heap and record the player who moved."""
        if name in self.heaps and removed <= self.heaps[name]:
            self.heaps[name] -= removed
            self.last_player = player
        else:
            raise ValueError("Invalid move")

# Example usage:
