class RockPaperScissors:
    """Simple rock-paper-scissors game with a beats mapping and a winner lookup."""

    _BEATS = {
        'rock': 'scissors',
        'paper': 'rock',
        'scissors': 'paper',
    }

    @classmethod
    def is_valid_move(cls, move: str) -> bool:
        """Return True if the move is one of the three allowed values."""
        return move in cls._BEATS

    @classmethod
    def determine_winner(cls, player1_move: str, player2_move: str) -> int:
        """
        Return the result of one round:
          0 if the round is a tie,
          1 if player 1 wins,
          2 if player 2 wins.

        Raises:
            ValueError: if either move is not recognised.
        """
        p1 = player1_move.lower()
        p2 = player2_move.lower()

        if not (cls.is_valid_move(p1) and cls.is_valid_move(p2)):
            raise ValueError(f'Valid moves are: {list(cls._BEATS)}')

        if p1 == p2:
            return 0  # tie

        if cls._BEATS[p1] == p2:
            return 1  # player 1 beats player 2

        return 2  # player 2 wins


if __name__ == '__main__':
