    p1, p2 = 'rock', 'scissors'
    result = game.determine_winner(p1, p2)
    outcomes = {0: 'Tie', 1: 'Player 1 wins', 2: 'Player 2 wins'}
    print(f'{p1} vs {p2}: {outcomes[result]}')
