class TodoItem:
    """A single task in a todo list."""

    def __init__(self, text, open=True):
        self.text = text
        self.open = open

    def check(self):
        self.open = False

    def uncheck(self):
        self.open = True


class TerminalTodoList:
    """A list of items that prints as a checklist with symbols.

    Example:

        list_ = TerminalTodoList(['Buy milk', 'Write email'])
        list_.check(0)
        print(list_)

    prints:

        ☑ Buy milk
        ☐ Write email
    """

    TEMPLATE = '{symbol} {text}'

    def __init__(self, tasks=None):
        self.items = [TodoItem(text) for text in tasks] if tasks else []

    def add(self, text):
        self.items.append(TodoItem(text))

    def check(self, index):
        self._require_index(index)
        self.items[index].check()

    def uncheck(self, index):
        self._require_index(index)
        self.items[index].uncheck()

    def clear(self):
        self.items = []

    def __getitem__(self, index):
        self._require_index(index)
        return self.items[index]

    def __len__(self):
        return len(self.items)

    @staticmethod
    def _require_index(index):
        if not isinstance(index, int):
            raise TypeError('index must be an int')
        if index < 0 or index >= len(self.items):
            raise IndexError('index out of range')

    def __repr__(self):
        lines = [
            self.TEMPLATE.format(
                symbol='☑' if not item.open else '☐',
                text=item.text,
            )
            for item in self.items
        ]
        return '\n'.join(lines)


