class SalesSummaryTable:
    """Render a table with a header row, aligned columns, and a dash divider.

    Header values and row values are stringified. Numbers (int or float)
    are right-aligned, and all other values are left-aligned. Column width
    is calculated from the header text and from all rows for that column.

    Example:

        from sales_table import SalesSummaryTable

        headers = ['Region', 'Orders', 'Revenue']
        rows = [
            ['North', 13, 4192.5],
            ['South', 7, 1860.0],
            ['East', 22, 11450.0],
            ['West', 11, 8390.3],
        ]

        table = SalesSummaryTable(headers, rows, column_formats={2: '{:,.2f}'})
        print(table.render())
    """

    def __init__(self, headers, rows, column_formats=None):
        """Create a summary table.

        Args:
            headers: A sequence of column names.
            rows: A sequence of row values, one row per sequence.
            column_formats: Optional dict mapping column indices to format strings.
                The format string is applied with `format(value)`.
        """
        self.headers = list(headers)
        self.rows = [list(row) for row in rows]
        self.formatters = column_formats or {}

        self._check_shape()
        self.column_widths = self._compute_widths()

    def _check_shape(self):
        header_len = len(self.headers)
        for row in self.rows:
            if len(row) != header_len:
                raise ValueError(f'Row length {len(row)} does not match header length {header_len}.')

    def _compute_widths(self):
        widths = [len(str(header)) for header in self.headers]

        for row in self.rows:
            for idx, cell in enumerate(row):
                widths[idx] = max(widths[idx], len(str(cell)))

        return widths

    def _fmt_cell(self, value, width, idx):
        """Return a string of exactly `width` characters."""
        fmt = self.formatters.get(idx)
        if fmt:
            cell = fmt.format(value)
        else:
            cell = '' if value is None else str(value)

        # Numbers (int, float, and subclasses of them) are right-aligned.
        # Everything else is left-aligned.
        if isinstance(value, (int, float)):
            return cell.rjust(width)
        return cell.ljust(width)

    def _format_row(self, values):
        return '  '.join(
            self._fmt_cell(v, w, i) for i, (w, v) in enumerate(zip(self.column_widths, values))
        )

    def _make_divider(self):
        return '  '.join('-' * w for w in self.column_widths)

    def render(self):
        """Return the formatted table as a string, including newlines."""
        lines = [
            self._format_row(self.headers),
            self._make_divider(),
        ]

        lines.extend(self._format_row(row) for row in self.rows)
        return '\n'.join(lines) + '\n'


if __name__ == '__main__':
    headers = ['Region', 'Orders', 'Revenue']
    rows = [
        ['North', 13, 4192.5],
        ['South', 7, 1860.0],
        ['East', 22, 11450.0],
        ['West', 11, 8390.3],
    ]

    table = SalesSummaryTable(headers, rows, column_formats={2: '{:,.2f}'})
    print(table.render())
