import sys


class TodoList:
    """A minimal terminal todo list that prints each item with a checkbox."""

    def __init__(self):
        self._items = []

    def add(self, description):
        """Add a new unchecked task."""
        self._items.append({"desc": description, "done": False})

    def complete(self, index):
        """Mark the task at *index* as done. Index is 1-based for convenience."""
        zero_based = index - 1
        if 0 <= zero_based < len(self._items):
            self._items[zero_based]["done"] = True
        else:
            raise IndexError(f"Task number {index} does not exist")

    def incomplete(self, index):
        """Mark the task at *index* as not done."""
        zero_based = index - 1
        if 0 <= zero_based < len(self._items):
            self._items[zero_based]["done"] = False
        else:
            raise IndexError(f"Task number {index} does not exist")

    def __str__(self):
        lines = []
        for i, item in enumerate(self._items, start=1):
            box = "☑" if item["done"] else "☐"
            lines.append(f"{i}. {box} {item[\"desc\"]}")
        return "\n".join(lines)

    def show(self, file=sys.stdout):
        """Print the list to *file*."""
        print(self.__str__(), file=file)


if __name__ == "__main__":
    todo = TodoList()
    todo.add("Buy milk")
    todo.add("Reply to the design review")
    todo.add("Schedule the team lunch")
    todo.complete(1)
    todo.show()
    # Output:
    # 1. ☑ Buy milk
    # 2. ☐ Reply to the design review
    # 3. ☐ Schedule the team lunch

