class PhoneSanitizer:
    """Normalizes plain-text phone numbers to a stable digit-only form."""

    _country_prefixes = {"1"}

    def __init__(self, raw):
        self.raw = raw

    def digits(self):
        """Return the numeric characters in the original input, in order."""
        return "".join(c for c in self.raw if "0" <= c <= "9")

    def strip_prefix(self, number):
        """Drop a leading country code if it appears in the configured set."""
        for prefix in self._country_prefixes:
            if number.startswith(prefix):
                return number[len(prefix) :]
        return number

    def format_grouped(self, number):
        """Insert dashes every four digits. The final group may be shorter."""
        groups = [number[i : i + 4] for i in range(0, len(number), 4)]
        return "-".join(groups)

    def number_snippet(self, number):
        """Return a message showing the cleaned number in a fixed form."""
        formatted = self.format_grouped(number)
        return f"got digits: {formatted}"

    def cleaned(self):
        """Return the raw input as a stabilized, printed string."""
        pure = self.digits()
        body = self.strip_prefix(pure)
        return self.number_snippet(body)


# Example
if __name__ == "__main__":
    sample = " +1 (555) 123-4567, office line"
    print(PhoneSanitizer(sample).cleaned())
