import re


class PhoneNumberCleaner:
    """Utility for normalizing US phone numbers.

    A clean phone number contains exactly 10 digits: the country prefix `1` is
    removed when present, and the result is formatted as ``AAA-BBB-CCCC``.
    """

    _DIGIT_PATTERN = re.compile(r'\d+')
    _DEFAULT_GROUP_SEPARATORS = '-'

    def __init__(self, line):
        """Create a cleaner for a single raw line of input.

        Parameters
        ----------
        line : str
            The submitted phone number, in any common format.

        Raises
        ------
        ValueError
            If the cleaned number does not have exactly 10 digits.
        """
        self._raw_line = line or ''
        cleaned = self._clean_to_digits(self._raw_line)

        if cleaned.startswith('1'):
            cleaned = cleaned[1:]

        if len(cleaned) != 10:
            raise ValueError(f"Number requires exactly 11 digits (including a leading '1') or 10 digits without it; got {len(cleaned)} from {repr(self._raw_line)}")

        self._cleaned = cleaned
        self._formatted = self._format_cleaned(cleaned)

    @property
    def raw(self):
        """The input line with no modification."""
        return self._raw_line

    @property
    def digits(self):
        """The 10-digit string without any separators."""
        return self._cleaned

    @property
    def formatted(self):
        """The normalized number in three groups separated by dashes."""
        return self._formatted

    @property
    def message(self):
        """Human-readable output showing the cleaned and formatted number."""
        return f'From {repr(self._raw_line)} got {self._cleaned} formatted as {self._formatted}'

    @classmethod
    def _clean_to_digits(cls, line):
        """Return only the digit characters from a string."""
        return ''.join(cls._DIGIT_PATTERN.findall(str(line or '')))

    @staticmethod
    def _format_cleaned(digits):
        """Return digits grouped as AAA-BBB-CCCC."""
        return f'{digits[:3]}{PhoneNumberCleaner._DEFAULT_GROUP_SEPARATORS}{digits[3:6]}{PhoneNumberCleaner._DEFAULT_GROUP_SEPARATORS}{digits[6:]}'
