class Rps:
    """A minimal rock‑paper‑scissors helper."""

    _wins_over = {
        "rock": "scissors",
        "paper": "rock",
        "scissors": "paper",
    }

    def __init__(self, rounds=1, default="rock"):
        if default not in self._wins_over:
            raise ValueError(f"invalid default move: {default!r}")
        if rounds < 1:
            raise ValueError("rounds must be at least 1")
        self.rounds = rounds
        self.default = default

    @classmethod
    def beats(cls, move):
        """Return the move that `move` defeats, or None if unknown."""
        return cls._wins_over.get(move)

    @classmethod
    def winner(cls, player, computer):
        """Return 'player', 'computer', or 'draw' for one round."""
        if player not in cls._wins_over or computer not in cls._wins_over:
            return None
        if player == computer:
            return "draw"
        return "player" if cls._wins_over[player] == computer else "computer"

    def play(self, player_move, computer_move):
        outcome = self.winner(player_move, computer_move)
        result = {
            "player": player_move,
            "computer": computer_move,
            "outcome": outcome,
        }
        return result

    @staticmethod
    def best_move_against(move):
        """Return the move that defeats `move`."""
        for candidate, beats in Rps._wins_over.items():
            if beats == move:
                return candidate
        return None
