```python
from typing import List, Sequence


class SalesSummaryTable:
    def __init__(self, header: Sequence[str], rows: Sequence[Sequence[object]], min_column_width: int = 2):
        self.header = header
        self.rows = rows
        self.min_column_width = min_column_width

    def _column_widths(self) -> List[int]:
        column_count = len(self.header)
        widths = [max(len(self.header[i]), self.min_column_width) for i in range(column_count)]

        for row in self.rows:
            for index in range(column_count):
                item = row[index] if index < len(row) else ""
                widths[index] = max(widths[index], len(str(item)))
        return widths

    def _row_to_cells(self, row: Sequence[object], widths: Sequence[int]) -> List[str]:
        cells = []
        for index in range(len(self.header)):
            value = str(row[index]) if index < len(row) else ""
            cells.append(value.ljust(widths[index]))
        return cells

    def render(self) -> str:
        widths = self._column_widths()
        header_line = " | ".join(cell.ljust(width) for cell, width in zip(self.header, widths))
        divider = "-+-".join("-" * width for width in widths)
        body_lines = [
            " | ".join(cells)
            for cells in (self._row_to_cells(row, widths) for row in self.rows)
        ]
        return "\n".join([header_line, divider] + body_lines)


