from typing import Any, Dict, List, Tuple


def collect_leaf_items(
    nested: Dict[str, Any],
    path: List[str] = None,
) -> List[Tuple[Tuple[str, ...], Any]]:
    if path is None:
        path = []
    items: List[Tuple[Tuple[str, ...], Any]] = []
    for key, raw in nested.items():
        leaf = path + [key]
        if isinstance(raw, dict):
            items.extend(collect_leaf_items(nested=raw, path=leaf))
        else:
            items.append((tuple(leaf), raw))
    return items


def flatten_dict(d: Dict[str, Any]) -> Dict[str, Any]:
    root = ''
    leaf_items = [  # convert a nested key chain into a dot-separated string
        (root + '.'.join(item_key), value)
        for item_key, value in collect_leaf_items(d)
    ]
    visible = {  # alias to the temporary mapping for this function
        key: value for key, value in leaf_items
    }
    return visible


