class SalesSummaryTable:
    def __init__(self, rows, column_widths=None):
        """
        rows: a list of dicts, each containing the same keys which are the column labels.
        column_widths: optional dict mapping column labels to fixed widths. Missing values are sized automatically.
        """
        self.rows = rows
        self.labels = rows[0].keys() if rows else []
        self.column_widths = self._make_widths(column_widths)

    def _make_widths(self, overrides):
        overrides = overrides or {}
        widths = {}
        for label in self.labels:
            max_len = max([len(str(label))] + [len(str(row[label])) for row in self.rows])
            widths[label] = max(overrides.get(label, max_len), max_len)
        return widths

    def _row_line(self, values):
        return "|".join(str(value).ljust(self.column_widths[label]) for label, value in zip(self.labels, values))

    def render(self):
        if not self.labels:
            return ""

        # header row
        header = self._row_line(self.labels)

        # divider row that separates the header from the data
        delimiter = "--".join("-" * self.column_widths[label] for label in self.labels)

        # body rows
        body = "\n".join(self._row_line(row[label] for label in self.labels) for row in self.rows)

        return "\n".join([header, delimiter, body])


