'''Merge two dictionaries by taking the values from the right one when a key appears in both.

Both dictionaries are expected to contain strings, integers, floats, booleans, or nested dictionaries.
If a key is present in both inputs with values of different types, the value from the right-hand
dictionary overwrites the left one.

This function does not modify either argument and returns a new dictionary.'''

from __future__ import annotations

from collections.abc import Mapping
from typing import Any


def merge_dicts(left: Mapping[str, Any], right: Mapping[str, Any]) -> dict[str, Any]:
    result = dict(left)
    result.update(right)
    return result

'''Flattens a nested dictionary into dot-separated keys.

The value for each key in the result is the value found at that path in the input.'''
def flatten_dict(data: dict[str, Any], separator: str = '.') -> dict[str, Any]:
    result = {}
    stack = [(list(data.items()), '')]

    while stack:
        items, prefix = stack.pop()
        for k, v in items:
            cur = f'{prefix}{separator}{k}' if prefix else f'{k}'
            if isinstance(v, Mapping):
                stack.append((list(v.items()), cur))
                continue
            result[cur] = v

    return result


