import re
from typing import Any, List


def extract_emails(response: Any, sep: str = ',', default: str = '') -> str:
    """
    Extract all email addresses from a nested API response.

    Arguments:
        response: The loaded response. It may be a dict, list, or any value.
        sep: Separator used to join the email addresses. Defaults to ','.
        default: Return value when no email address is found.  Defaults to ''.

    Returns:
        A single string containing every email address joined by the separator,
        or the default value when none is found.

    Notes:
        Demonstration code. Matches working RFC 5322 usernames, doesn't aim to
        validate domains fully.
    """
    # Rough pattern that covers most usernames and domains
    email_pattern = re.compile(r'[A-Za-z0-9_.+-]+@[A-Za-z0-9-]+\.[A-Za-z]{2,}', re.I)

    def collect(container: Any, matches: List[str]) -> None:
        if isinstance(container, str):
            matches.extend(email_pattern.findall(container))
        elif isinstance(container, dict):
            for value in container.values():
                collect(value, matches)
        elif isinstance(container, list):
            for item in container:
                collect(item, matches)
        elif isinstance(container, tuple):
            for item in container:
                collect(item, matches)
        # Other built-in containers, such as set, can be added in the same way
        elif isinstance(container, set):
            for item in container:
                collect(item, matches)

    found: List[str] = []
    collect(response, found)

    return sep.join(found) if found else default


