def merge_settings(default, user):
    if not isinstance(default, dict):
        print('warning: default is not a dict. using an empty baseline.')
        default = {}
    merged = dict(default)
    if isinstance(user, dict):
        merged.update(user)
    elif user is not None:
        print('warning: user settings is not a dict; ignored')
    return merged
