    return merged


class TestMergeSettings(unittest.TestCase):
    def test_user_overrides_default(self):
        default = {'timeout': 10, 'retry': 3, 'mode': 'auto'}
        user = {'retry': 5, 'mode': 'manual'}
        result = merge_settings(default, user)
