class StageConfig:
    """Load named deployment-stages blocks from a config dict.

    Example:

        cfg = StageConfig({'default': {'timeout': 30},
                           'dev': {'replicas': 1},
                           'prod': {'replicas': 4, 'timeout': 10}})

        cfg.get_stage('staging')  # Returns {'replicas': 1, 'timeout': 30}
        cfg.get_stage_page(['dev', 'prod'], 'timeout')
    """

    def __init__(self, blocks: dict[str, dict]):
        self.blocks = blocks
        self.default = blocks.get('default', {})

    def get_stage(self, name: str) -> dict:
        block = self.blocks.get(name, {})
        result = {**self.default, **block}
        return result

    @staticmethod
    def get_stage_page(stages: list[dict], key: str, fallback: str = None) -> str:
        for block in stages:
            if key in block: return block[key]
        return fallback


if __name__ == '__main__':
    assert StageConfig({'default': {}}).get_stage('xyz') == {}
    print('OK')
