def mask_card_value(value: str) -> str:
    """Mask a credit-card value, leaving only the last four characters visible."""
    if not isinstance(value, str):
        return ''
    last_four = value[-4:] if len(value) >= 4 else value
    return '*' * max(len(value) - 4, 0) + last_four


def mask_cards(obj: Any, keys=('card', 'number', 'pan')) -> Any:
    """Return a copy of the JSON object with card values masked.

    The function handles dictionaries, lists, and nested structures.
    It matches keys case-insensitively.
