    if isinstance(obj, dict):
        masked = {}
        for k, v in obj.items():
            if isinstance(v, (dict, list)):
                masked[k] = mask_cards(v, keys)
            elif any(part in k.lower() for part in keys):
                masked[k] = mask_card_value(v)
            else:
                masked[k] = v
        return masked
    if isinstance(obj, list):
        return [mask_cards(item, keys) for item in obj]
    return obj


