import re
from typing import Any, Dict


def _mask_number(number: str) -> str:
    """
    Replace every character in *number* except the last four digits with an asterisk.

    Characters that are not digits pass through unchanged. This means that
    formatted numbers such as "1234-5678-9012-3456" keep their separators.
    """
    masked = []
    digits_seen = 0

    # Scan the string from right to left so we know when we have reached the last four digits.
    for ch in reversed(number):
        if ch.isdigit():
            if digits_seen >= 4:
                masked.append('*')
            else:
                masked.append(ch)
            digits_seen += 1
        else:
            masked.append(ch)

    return ''.join(reversed(masked))


def mask_credit_cards(data: Any) -> Any:
    """
    Recursively walk through *data* and mask values associated with credit card keys.

    Any key containing "card", "cc", "pan", "cvc", or "account" (case-insensitive)
    gets its value passed through :func:`_mask_number`. Nested structures such
    as dictionaries inside lists are handled as well.
    """
    if isinstance(data, dict):
        return {k: mask_credit_cards(v) if not isinstance(v, str) else
                (_mask_number(v) if re.search(r'\b(card|cc|pan|cvc|account)\b', k, re.IGNORECASE) else v)
                for k, v in data.items()}
    if isinstance(data, list):
        return [mask_credit_cards(item) for item in data]
    return data


