from copy import deepcopy


def _is_credit_card_number(text):
    """Return True if the text looks like a card number: 13 to 19 digits."""
    if not isinstance(text, str):
        return False
    digits = text.strip().replace(" ", "")
    return 13 <= len(digits) <= 19 and digits.isdigit()


def _mask_number(number):
    """Leave the last four characters visible, replace the rest with asterisks."""
    visible = 4
    if len(number) <= visible:
        return "*" * len(number)
    return "*" * (len(number) - visible) + number[-visible:]


def _mask_card_string(text):
    """Return a masked copy of text, handling grouped digits like '1234 5678'."""
    if not _is_credit_card_number(text):
        return text

    cleaned = text.strip()
    delimiter = ""
    for sep in (" ", "-"):
        if sep in cleaned:
            delimiter = sep
            break

    if delimiter:
        parts = cleaned.split(delimiter)
        cleaned = "".join(parts)

    return _mask_number(cleaned)


def _mask_in_value(value):
    if isinstance(value, str):
        return _mask_card_string(value)
    if isinstance(value, dict):
        return {k: _mask_in_value(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_mask_in_value(item) for item in value]
    return value


def mask_credit_cards(record):
    """Return a new copy of record with credit-card-looking strings masked.

    Credit card numbers are detected by their length and digit-only content.
    Input is copied, so the original is left unchanged.
    """
    return _mask_in_value(deepcopy(record))
```

