```python
class SemiSummary:
    """
    Reads a semicolon-separated text input and reports row and column counts.

    Public methods:
        summarize(text)
        is_empty(text)

    The summary is a single sentence. If the input is blank or contains only
    whitespace, summarize returns the no-data message.
    """

    def __init__(self, separator=';'):
        if not isinstance(separator, str):
            raise TypeError(f'separator must be a string, got {type(separator).__name__}')
        if separator == '':
            raise ValueError('separator cannot be an empty string')
        self.separator = separator

    def _split_lines(self, text):
        # Keeps empty lines only when the input contains a line feed.
        for line in text.splitlines():
            if line.strip():
                yield line

    def summarize(self, text):
        if self.is_empty(text):
            return 'No data.'

        rows = self._split_lines(text)
        first = next(rows, None)

        if first is None:
            return 'No data.'

        row_count = 1
        col_count = first.count(self.separator) + 1

        for line in rows:
            row_count += 1
            # Stop checking col_count after we have at least two rows.
            if col_count > 0 and row_count == 2:
                alt = line.count(self.separator) + 1
                if alt > col_count:
                    col_count = alt

        return f'{row_count} rows, {col_count} columns.'

    def is_empty(self, text):
        return not isinstance(text, str) or not text.strip()
```

