def mask_card_numbers(obj):
    """
    Copy *obj* and replace the values of any keys named "cardNumber" or "cvv"
    with a masked version.

    Card-like values are masked so that only the last four characters remain
    visible. If a matching value is shorter than four characters, the value is
    replaced with an empty string.

    The function accepts Python objects that result fromjson.loads, such as nested
    dictionaries and lists containing strings, numbers, booleans, and None, and
    returns a new, fully masked object. Keys that are not strings are left
    untouched.

    The returned object can be passed to json.dumps without further processing.
    """

    def mask_value(val):
        # Values that are not strings are normalised to a string for masking.
        text = str(val)
        if len(text) <= 4:
            return ""
        return "*" * (len(text) - 4) + text[-4:]

    def walk(item):
        if isinstance(item, Mapping):
            return replace(item)
        if isinstance(item, list):
            return [walk(entry) for entry in item]
        return item

    def replace(source):
        protected = {"cardNumber": True, "cvv": True}
        result = {}
        for key, value in source.items():
            if key in protected:
                result[key] = mask_value(value)
            else:
                result[key] = walk(value)
        return result

    if not isinstance(obj, Mapping):
        raise TypeError("mask_card_numbers expects a dict-like root object")
