import random

class Nim:
    def __init__(self, heaps):
        self.heaps = [int(h) for h in heaps]

    def status(self):
        labels = ['A', 'B', 'C', 'D', 'E']
        parts = [f'Heap {labels[i]}: {n}' for i, n in enumerate(self.heaps) if n > 0]
        return ' | '.join(parts) or 'All heaps are empty.'

    def move(self, index, count):
        if 0 <= index < len(self.heaps) and 1 <= count <= self.heaps[index]:
            self.heaps[index] -= count
            return True
        return False

    def empty(self):
        return all(h == 0 for h in self.heaps)

    def winner(self):
        return 'Player 2' if self.empty() else 'Game continues'


