class TinyNim:
    """A minimal Nim game with a textual status line and a winner declaration."""

    LABELS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    def __init__(self, heaps, starting_player='Player 1'):
        """Create the game with a list of heap sizes and the player to move first."""
        if not heaps:
            raise ValueError('heaps must contain at least one heap')
        if len(heaps) > len(self.LABELS):
            raise ValueError('maximum supported heaps is {}'.format(len(self.LABELS)))
        self.heaps = list(map(int, heaps))
        self.next_player = starting_player
        self.last_player = None

    def status(self):
        """Return a single line showing each heap with labels 'Heap A', 'Heap B', etc.

        Example: 'Heap A: 3 | Heap B: 5'.
        Empty heaps are shown with a count of zero so that the layout never drops
        labels between moves.
        """
        parts = []
        for label, count in zip(self.LABELS, self.heaps):
            parts.append(f'Heap {label}: {count}')
            if len(parts) == len(self.heaps):
                break
        return ' | '.join(parts)

    def remove(self, heap_index, count):
        """Take `count` objects from heap number `heap_index` (zero based).

        The method raises an exception for an empty or negative move so that a
        caller cannot silently produce an invalid game state. The player to move
        is switched only when the move is legal.
        """
        if heap_index < 0 or heap_index >= len(self.heaps):
            raise IndexError('heap index out of range')
        if count <= 0:
            raise ValueError('count must be positive')
        if count > self.heaps[heap_index]:
            raise ValueError('move removes more objects than are present')
        if self.is_finished():
            raise RuntimeError('game already finished')
        self.heaps[heap_index] -= count
        self.last_player = self.next_player
        self.next_player = ('Player 2' if self.next_player == 'Player 1'
                            else 'Player 1')

    def is_finished(self):
        """Return True when every heap is empty."""
        return all(count == 0 for count in self.heaps)

    def winner(self):
        """Return the last player if the game is finished; otherwise return None."""
        return self.last_player if self.is_finished() else None


# Example of use
if __name__ == '__main__':
    game = TinyNim([3, 5])
    print(game.status())              # 'Heap A: 3 | Heap B: 5'
    game.remove(0, 3)
    print(game.status())              # 'Heap A: 0 | Heap B: 5'
    game.remove(1, 5)
    print(game.status())              # 'Heap A: 0 | Heap B: 0'
    print(game.winner())              # 'Player 2'
```

Here is a small, self-contained function that walks a nested structure, finds strings that look like a credit‑card number, and replaces every character except the last four with asterisks. It keeps the surrounding JSON shape intact, so you can plug it into whatever loader or serializer you already use.

The regular expression is deliberately strict. It matches blocks of 12 to 19 digits, which is the length range used by most payment networks, and it also accepts a second block after a separator such as a space or a dash. If the pattern is too permissive for your data, you can tighten it from outside the function to suit your agency's format rules.

```python
import re
import json
from typing import Any

CARD_PATTERN = re.compile(
    r"(?P<all>(?P<prefix>\b(?:\d[ -]*){12,19}\d\b))",
    re.IGNORECASE,
)

def mask_card(match: re.Match) -> str:
    digits = re.sub(r"[ -]", "", match.group("all"))
    if len(digits) < 4:
        return match.group("all")
    masked = "*" * (len(digits) - 4) + digits[-4:]
    return masked[-len(match.group("all")) :] if len(match.group("all")) < len(masked) else masked


def mask_sensitive(data: Any) -> Any:
    if isinstance(data, dict):
        return {k: mask_sensitive(v) for k, v in data.items()}
    if isinstance(data, list):
        return [mask_sensitive(item) for item in data]
    if isinstance(data, str):
        return CARD_PATTERN.sub(mask_card, data)
    return data


if __name__ == "__main__":
    example = {
        "user": "Rashida Okafor",
        "payments": [
            {"method": "card", "number": "4111 1111 1111 0456", "date": "09/28"},
            {"method": "card", "number": "5555-5555-5555-1234", "date": "10/29"},
            {"method": "netbank", "account": "IT09RAPP6030000031811018"},
        ],
        "note": "First client, four cards total",
    }

    cleaned = mask_sensitive(example)
    print(json.dumps(cleaned, indent=4, sort_keys=False))
