The function walks nested dictionaries and lists so that data at any depth is masked. The regular expression is kept deliberately permissive so that numbers written with or without spaces or dashes are handled. If your ingest pipeline already excludes credit-card data, you can drop this function and skip the check.

```python
import re
import copy
import json

# A loose pattern that matches common 13 to 19 digit credit-card numbers,
# allowing optional spaces or dashes between digit groups.
_CARD_NUMBER_RE = re.compile(
    r"(?<!\d)(?:(\d[ -]*?){13,19})(?!\d)"
)

def _mask_match(match):
    group = re.sub(r"[^\d]", "", match.group(0))
    if len(group) < 4:
        return match.group(0)
    masked_part = "*" * (len(group) - 4)
    visible_part = group[-4:]
    return f"{masked_part}{visible_part}"

def _mask_value(value):
    if isinstance(value, str):
        return _CARD_NUMBER_RE.sub(_mask_match, value)
    if isinstance(value, dict):
        return {k: _mask_value(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_mask_value(item) for item in value]
    return value

def mask_sensitive_fields(document):
    """Return a copy of *document* with credit-card numbers masked.

    The function does not modify the input in place. String values are
    scanned with the card-number pattern above, and identified numbers
    are replaced with partial masks.

    Parameters
    ----------
    document : dict or list
        Parsed JSON that may contain nested dictionaries or lists.

    Returns
    -------
    dict or list
        A new data structure with masked values; the type matches the input.
    """
    document = copy.deepcopy(document)
    return _mask_value(document)


# Example usage
