            f'Valid next steps: {self._valid_next(expected)}.'
        )
        super().__init__(message)
        self.order_id = order_id
        self.expected = expected
        self.attempted = attempted

    @staticmethod
    def _valid_next(state):
        index = list(OrderStep).index(state) + 1
        return ', '.join([step.value for step in list(OrderStep)[index:]])


class Order:
    def __init__(self, order_id):
        self.id = order_id
        self.state = OrderStep.PLACED

    @staticmethod
    def _allowed_transitions(state):
        mapping = {
            OrderStep.PLACED: OrderStep.PACKED,
            OrderStep.PACKED: OrderStep.SHIPPED,
            OrderStep.SHIPPED: OrderStep.DELIVERED,
        }
        return mapping.get(state, None)

    def advance(self, next_state):
        if next_state not in OrderStep:
            raise ValueError(f'{next_state} is not a valid {OrderStep.__name__}')

        expected = self._allowed_transitions(self.state)
        if expected is None:
            raise InvalidTransitionError(self.id, self.state.value, next_state.value)

        if expected != next_state:
            raise InvalidTransitionError(self.id, self.state.value, next_state.value)

        self.state = next_state

    def __repr__(self):
        return f'<Order {self.id} state={self.state.value}>'


# Demo: sequential moves
order = Order(101)
order.advance(OrderStep.PACKED)
order.advance(OrderStep.SHIPPED)
order.advance(OrderStep.DELIVERED)

# Demo: an illegal jump gives a specific error
try:
    too_fast = Order(200)
    too_fast.advance(OrderStep.SHIPPED)
except RuntimeError as exc:
    print(exc)
```

Here is a small function that walks through a JSON‑decoded Python dictionary and replaces any credit card number it finds with a masked version that keeps the last four digits visible and covers the rest with asterisks. It only touches values that are strings and that look like plausible credit card numbers (13 to 19 digits). The function returns a new dictionary so the original input is unchanged.

```python
import re
from copy import deepcopy

MASKED_CARD_PATTERN = re.compile(r"(?P<digits>\d{13,19})")


def mask_card(value: str) -> str:
    """Return a masked version of a credit card number, keeping the last four digits."""
    prefix = value[:-4]
    suffix = value[-4:]
    return f"{\"*\" * len(prefix)}{suffix}"


def mask_credit_cards(item):
    """Recursively mask credit card numbers in a JSON-decoded structure."""
    if isinstance(item, dict):
        copy = deepcopy(item)
        for key, value in copy.items():
            copy[key] = mask_credit_cards(value)
        return copy

    if isinstance(item, list):
        return [mask_credit_cards(element) for element in item]

    if isinstance(item, str):
        # If the entire string is a plausible card number, mask it.
        if MASKED_CARD_PATTERN.fullmatch(item):
            return mask_card(item)
        # Otherwise find any card-like substrings inside a longer string.
        return (
            item
            if not MASKED_CARD_PATTERN.search(item)
            else MASKED_CARD_PATTERN.sub(lambda m: mask_card(m.group(0)), item)
        )

    return item


# Example usage
if __name__ == "__main__":
    example = {
        "user": "alice",
        "card_number": "4111111111111111",
        "orders": [
            {"id": 1, "amount": 25.0},
            {"id": 2, "payment": {"card": "5500000000000004", "status": "settled"}},
        ],
    }
    print(mask_credit_cards(example))
```

