**`utils/serializer.py`**

```python
"""utils.serializer

Simple serialization of Python objects into a JSON-friendly dictionary.

Objects are converted into a dictionary containing two keys:

    { 'kind': 'ClassName', 'payload': { ... fields ... } }

Only the class name and the object's public fields are stored. No code is
executed during deserialization, and classes must be registered before they can
be reconstructed.

Example:

    >>> from utils.serializer import ObjectSerializer
    >>> from collections import namedtuple
    >>> Point = namedtuple('Point', 'x y')
    >>> p = Point(1, 2)
    >>> ObjectSerializer.register(Point)
    >>> serialized = ObjectSerializer.dump(p)
    >>> serialized
    {'kind': 'Point', 'payload': {'x': 1, 'y': 2}}
    >>> ObjectSerializer.load(serialized)
    Point(x=1, y=2)

Limitations:

* An object whose fields cannot be represented as JSON primitives will fall back
  to its string representation.
* Custom classes must be registered before `load` is called.
* Nested custom objects are serialized recursively only if their classes are
  registered.
* Circular references are not detected and will raise `RecursionError`.

"""

import inspect
from collections.abc import Mapping, Sequence
from types import MappingProxyType
from typing import Any, Callable, Dict, Type

__all__ = ['ObjectSerializer', 'SerializationError']


class SerializationError(RuntimeError):
    """Raised when an object cannot be serialized or deserialized."""
    pass


def _is_primitive(value: Any) -> bool:
    return isinstance(value, (int, float, bool, str, type(None)))


def _as_primitive(value: Any) -> Any:
    """Return a JSON-primitive representation or raise SerializationError."""
    if _is_primitive(value):
        return value
    if isinstance(value, (list, tuple)):
        return [_as_primitive(x) for x in value]
    if isinstance(value, Mapping):
        return {str(k): _as_primitive(v) for k, v in value.items()}
    if hasattr(value, '__dict__'):
        return _as_primitive(_shallow_dict(value))
    # Fallback: string representation for unknown types
    return str(value)


def _shallow_dict(obj: Any) -> Dict[str, Any]:
    """Return a shallow field dictionary for an object."""
    # Prefer __dict__; fall back to namedtuple/_asdict for other builtins.
    if hasattr(obj, '__dict__'):
        return dict(obj.__dict__)
    if hasattr(obj, '_asdict'):
        return dict(obj._asdict())  # noqa: SLF001 (namedtuple)
    # For a dataclass or slots-only object.
    fields = {}
    for name in getattr(obj, '__slots__', ()):
        try:
            fields[name] = getattr(obj, name)
        except AttributeError:
            continue
    return fields


class ObjectSerializer:
    """Serialize and deserialize objects to and from a dictionary structure.

    The serializer does not touch the object's class during reading or writing. It
    records the class name under ``'kind'`` and the object's public fields under
    ``'payload'``. Nested objects are serialized recursively if their classes have
    been registered with :meth:`register`.

    Example:

        >>> class Config:
        ...     __init__ = lambda self, host, port: (setattr(self, 'host', host), setattr(self, 'port', port))
        >>> ObjectSerializer.register(Config)
        >>> s = ObjectSerializer.dump(Config('localhost', 8080))
        >>> s
        {'kind': 'Config', 'payload': {'host': 'localhost', 'port': 8080}}
    """

    _registry: Dict[str, Callable[..., Any]] = MappingProxyType({})

    @classmethod
    def register(cls, obj_type: Type[Any]) -> None:
        """Register a class name for deserialization.

        If a class is registered once, further registrations for the same name
        are ignored.

        Args:
            obj_type: The class to register. Its name is used as the lookup key.

        Raises:
            ValueError: If ``obj_type`` is not a class.
        """
        if not inspect.isclass(obj_type):
            raise ValueError(f'register() argument must be a class, got {type(obj_type)}')
        if obj_type.__name__ not in cls._registry:  # type: ignore[no-any-return]
            cls._registry = {**cls._registry, obj_type.__name__: obj_type}  # type: ignore[assignment]

    @classmethod
    def dump(cls, obj: Any) -> Dict[str, Any]:
        """Serialize an object into {'kind': name, 'payload': data}.

        Args:
            obj: Any Python object. Dictionaries, lists, tuples, and registered
                custom classes are all supported. Unregistered custom classes are
                converted to a simple string under ``'payload'``.

        Returns:
            A JSON-friendly dictionary.

        Raises:
            SerializationError: If a field cannot be represented as a
                JSON primitive, unless the fallback is in use.
        """
        kind = type(obj).__name__
        if kind in cls._registry:
            payload = {}
            for name, value in _shallow_dict(obj).items():
                try:
                    payload[name] = _as_primitive(value)
                except Exception as exc:
                    raise SerializationError(f'field {name!r}: {exc}') from exc
        elif isinstance(obj, Mapping):
            kind = 'dict'
            payload = {str(k): _as_primitive(v) for k, v in obj.items()}
        elif isinstance(obj, Sequence) and not isinstance(obj, (str, bytes, bytearray)):
            kind = 'list'
            payload = [_as_primitive(v) for v in obj]
        else:
            kind = 'value'
            payload = _as_primitive(obj)
        return {'kind': kind, 'payload': payload}

    @classmethod
    def load(cls, data: Dict[str, Any]) -> Any:
        """Round-trip a dictionary back into its original object.

        Args:
            data: The dictionary returned by :meth:`dump`.

        Returns:
            The reconstructed object.

        Raises:
            SerializationError: If ``data`` cannot be deserialized, or the class
                name is not registered.
            KeyError: If the `'kind'` or `'payload'` keys are missing.
        """
        kind = data.get('kind')
        payload = data.get('payload')
        if kind is None or payload is None:
            raise SerializationError('dictionary must contain kind and payload')
        if kind == 'dict':
            return dict(payload)
        if kind == 'list':
            return list(payload)
        if kind == 'value':
            return payload
        if kind not in cls._registry:
            raise SerializationError(f'class {kind!r} is not registered')
        obj_type = cls._registry[kind]
        if inspect.isclass(obj_type):
            try:
                return obj_type(**payload)
            except TypeError as exc:
                raise SerializationError(f'cannot instantiate {kind}: {exc}') from exc
        raise SerializationError(f'registry entry for {kind} is not a class')
```

