import pytest

from utils.serializer import ObjectSerializer, SerializationError


class Simple:
    def __init__(self, name, count):
        self.name = name
        self.count = count


@pytest.fixture(autouse=True)
def clean_registry(monkeypatch):
    """Reset the registry before each test.

    The registry is a class-level attribute, so state would otherwise leak between
    tests. The tests do not depend on any built-in types, so an empty registry
    is sufficient.
    """
    monkeypatch.setattr(ObjectSerializer, '_registry', ObjectSerializer._registry.__class__())
    yield


def test_dump_basic_types():
    assert ObjectSerializer.dump(42) == {'kind': 'value', 'payload': 42}
    assert ObjectSerializer.dump('hello') == {'kind': 'value', 'payload': 'hello'}
    assert ObjectSerializer.dump([1, 2, 3]) == {'kind': 'list', 'payload': [1, 2, 3]}
    assert ObjectSerializer.dump({'a': 1}) == {'kind': 'dict', 'payload': {'a': 1}}


def test_dump_and_load_custom():
    Simple = Simple  # alias for clearer error output
    ObjectSerializer.register(Simple)
    obj = Simple('test', 7)
    serialized = ObjectSerializer.dump(obj)
    assert serialized['kind'] == 'Simple'
    payload = serialized['payload']
    assert 'name' in payload and payload['name'] == 'test'
    assert 'count' in payload and payload['count'] == 7
    result = ObjectSerializer.load(serialized)
    assert type(result) is Simple
    assert result.name == 'test'
    assert result.count == 7


def test_load_unregistered_fails():
    with pytest.raises(SerializationError, match='class Foo is not registered'):
        ObjectSerializer.load({'kind': 'Foo', 'payload': {'a': 1}})


def test_load_invalid_structure():
    with pytest.raises(SerializationError, match='must contain kind and payload'):
        ObjectSerializer.load({'payload': {'a': 1}})
    with pytest.raises(SerializationError, match='must contain kind and payload'):
        ObjectSerializer.load({'kind': 'dict'})


def test_load_invalid_init():
    class NeedTwo:
        def __init__(self, a, b):
            self.a = a
            self.b = b

    ObjectSerializer.register(NeedTwo)
    bad = {'kind': 'NeedTwo', 'payload': {'a': 1}}
    with pytest.raises(SerializationError, match='cannot instantiate NeedTwo'):
        ObjectSerializer.load(bad)
