class JobState:
    PENDING = "pending"
    RUNNING = "running"
    FAILED = "failed"
    DONE = "done"


class Job:
    def __init__(self, name):
        self.name = name
        self.state = JobState.PENDING
        self.attempts = 0

    def start(self):
        self.attempts += 1
        self.state = JobState.RUNNING

    def complete(self):
        self.state = JobState.DONE

    def fail(self):
        self.state = JobState.FAILED

    def reset(self):
        self.state = JobState.PENDING

    def status(self):
        return f"Job '{self.name}': {self.state} (attempt {self.attempts})"


def retry_job(job):
    if job.state == JobState.FAILED:
        job.reset()
        job.start()


if __name__ == "__main__":
    job = Job("export-report")
    print(job.status())
    job.start()
    job.fail()
    print(job.status())
    retry_job(job)
    print(job.status())
