Here is a minimal, self-contained class that checks for a set of required keys in a `dict` and raises a clear error if any are missing. Each message names exactly the key that is absent, which keeps unit failures readable and fixes easy to locate.

```python
from copy import deepcopy


class ConfigError(ValueError):
    """Configuration is incomplete or malformed."""


class MeridianConfig:
    """
    Validate an analytics platform configuration.

    Parameters
    ----------
    settings: dict
        A dictionary with string keys. Required keys are 'api_key' and 'region',
        plus whatever the surrounding service needs.

    Raises
    ------
    ValueError
        If any required key is missing.
    """

    DEFAULTS = {'region': 'us-east', 'timeout': 30}
    REQUIRED = {'api_key', 'region'}

    def __init__(self, settings):
        if not isinstance(settings, dict):
            raise TypeError('settings must be a dict, got %r' % type(settings))

        self._settings = deepcopy(settings)
        self._populate_defaults()
        self._check_missing_required(self._settings)

        self.api_key = self._settings['api_key']
        self.region = self._settings['region']
        self.timeout = self._settings['timeout']

    def _populate_defaults(self):
        """Fill in any default keys that are not already present."""
        for key, value in self.DEFAULTS.items():
            self._settings.setdefault(key, value)

    @staticmethod
    def _check_missing_required(mapping):
        """Raise an error naming each required key that is missing."""
        missing = MeridianConfig.REQUIRED - set(mapping) - set(
            k for k, v in mapping.items() if v is None
        )
        if missing:
            raise ConfigError('required %s missing: %s' % (
                'field' if len(missing) == 1 else 'fields',
                ', '.join(sorted(missing)),
            ))

    def get(self, key, default=None):
        """Look up a key without raising. Use for optional service values."""
        return self._settings.get(key, default)

    @property
    def as_tuple(self):
        """Return the three primary values in a stable order for logging."""
        return (self.api_key, self.region, self.timeout)


