**Job runner state machine**

This sample keeps job state out of the run loop so that retries, cancellation, and status reporting stay predictable. Each job knows its own state and retry count, and a retry call is the only thing that can move a `failed` job back to work.

```python
import random

# Pull requests that change these values should come with a matching test for
# every transition in the `with_state` table below.
PENDING = 'pending'
RUNNING = 'running'
FAILED = 'failed'
DONE = 'done'


class Job:
    def __init__(self, name, max_retries=3):
        self.name = name
        self.max_retries = max_retries
        self.attempt = 0
        self.state = PENDING

    def status(self) -> str:
        return f'{self.name}: attempt {self.attempt} is {self.state}'

    def reset(self):
        """Return a new job with the same name and retry limit."""
        new_job = Job(self.name, self.max_retries)
        new_job.attempt = self.attempt
        new_job.state = self.state
        return new_job

    def start(self):
        if self.state != PENDING:
            raise RuntimeError(f'cannot start job in state {self.state}')
        self.state = RUNNING
        self.attempt += 1

    def complete(self):
        if self.state != RUNNING:
            raise RuntimeError(f'cannot complete job in state {self.state}')
        self.state = DONE

    def fail(self):
        if self.state != RUNNING:
            raise RuntimeError(f'cannot fail job in state {self.state}')
        self.state = FAILED

    def retry(self):
        if self.state != FAILED:
            raise RuntimeError('retry is only allowed from the failed state')
        if self.attempt >= self.max_retries:
            raise RuntimeError('no retries remain')
        # Keeping the attempt count means the status message shows how many times
        # the job has been scheduled. The job runs with a reset state.
        self.state = PENDING

    def is_finished(self):
        return self.state in {DONE, FAILED and self.attempt >= self.max_retries}


class JobRunner:
    """A very small background loop that schedules jobs until they are finished."""
    def __init__(self):
        self.jobs = []

    def submit(self, job):
        self.jobs.append(job.reset())
        return job

    def run_once(self):
        for index, job in enumerate(list(self.jobs)):
            if job.state == PENDING:
                try:
                    job.start()
                    self._run(job)
                    job.complete()
                except Exception:
                    job.fail()
                finally:
                    print(job.status())

                    if job.state == FAILED and job.attempt < job.max_retries:
                        job.retry()
                        print(f'retrying {job.name}, now scheduled attempt {job.attempt + 1}')
                if job.is_finished():
                    self.jobs[index].state = DONE

    # Replace this with your real work. The random failure is for the demo.
    def _run(self, job):
        if random.random() < 0.4:
            raise RuntimeError(f'simulated failure for {job.name}')
        print(f'{job.name} worked on attempt {job.attempt}')


if __name__ == '__main__':
    runner = JobRunner()
    runner.submit(Job('alpha', max_retries=2))
    runner.submit(Job('beta', max_retries=4))

    # In a production runner you would want a stop flag and a backoff policy.
    while runner.jobs:
        runner.run_once()
