class PhoneNumberCleaner:
    """Cleans and formats phone numbers in a consistent, simple way.

    The cleaning rules are as follows.

    1. Keep only digit characters from the input.
    2. If the result contains eleven digits and its first digit is ``1``, drop that first digit.
    3. Return a dash-separated string in groups of three digits when the cleaned
       length is multiples of three. Any excess digits are placed in the final
       group, so a seven-digit number produces three groups of the form ``xxx-xxx-x``.

    These rules do not purport to reflect any national or international numbering plan.
    They apply the same transformation to every input.
    """

    _digit_group_sizes_10: Final[tuple[int, ...]] = (3, 3, 4)
    _digit_group_sizes_7: Final[tuple[int, ...]] = (3, 3, 1)

    @staticmethod
    def _rm_digit_like(s: str) -> str:
        return "".join(d for d in s if d in "0123456789")

    @classmethod
    def _rm_country_code(cls, s: str) -> str:
        if len(s) == 11 and s.startswith("1"):
            return s[1:]
        return s

    @classmethod
    def _group_digits(cls, s: str) -> list[str]:
        groups: list[str] = []
        start = 0
        remainder = len(s)
        while remainder >= 0:
            if remainder == 7:
                sizes = cls._digit_group_sizes_7
            elif remainder == 0:
                break
            elif remainder % 3 == 1 and remainder > 4:
                sizes = cls._digit_group_sizes_7
            else:
                sizes = cls._digit_group_sizes_10
                if sum(sizes) > remainder:
                    sizes = (remainder,)
            group = s[start:start + sizes[0]]
            groups.append(group)
            start += sizes[0]
            remainder = len(s) - start
        return groups

    @classmethod
    def clean_number(cls, s: str) -> str:
        no_letters = cls._rm_digit_like(s)
        normalized = cls._rm_country_code(no_letters)
        groups = cls._group_digits(normalized)
        return "-".join(groups) if groups else normalized

    @classmethod
    def format_as_message(cls, s: str) -> str:
        return cls.clean_number(s)

    @classmethod
    def format_with_dashes(cls, s: str) -> str:
        return f"{cls.clean_number(s)}"
