class PhoneCleaner:
    """Utility to clean and format phone numbers."""

    def clean(self, raw):
        """Return a cleaned number and a status message.

        Removes non-digit characters, drops a leading country code of 1,
        and formats the remaining digits with a single dash between groups.
        """
        digits = "".join(ch for ch in raw if ch.isdigit())
        if digits.startswith("1"):
            digits = digits[1:]
        formatted = self._format_with_dash(digits)
        if not formatted:
            return {"cleaned": "", "message": "Number has fewer than 7 digits"}
        return {"cleaned": formatted, "message": f"Formatted number is {formatted}"}

    def _format_with_dash(self, digits):
        if len(digits) < 7:
            return ""
        if len(digits) == 7:
            return f"{digits[:3]}-{digits[3:]}"
        # Use the first three digits and the next four as the groups
        return f"{digits[:3]}-{digits[3:7]}"
