        self.status = TicketStatus.ISSUED
        self.issue_date = issue_date
        self.amount_due = amount_due
        message = f'Ticket {self.id} issued to {self.driver_name}. Amount due: ${self.amount_due:.2f}.'
        self.notify_status(message)
        return message

    def pay(self, paid_date) -> str:
        if self.status in {TicketStatus.NOT_ISSUED, TicketStatus.CLOSED}:
            raise InvalidTransitionError(
                f'Cannot pay ticket when status is {self.status.name}.'
            )
        self.status = TicketStatus.PAID
        message = f'Ticket {self.id} paid on {paid_date} and is now closed.'
        self.notify_status(message)
        return message

