        if self.status != TicketStatus.ISSUED:
            raise InvalidTransitionError(
                f'Cannot contest ticket when status is {self.status.name}.'
            )
        self.status = TicketStatus.CONTESTED
        message = f'Ticket {self.id} contested for reason: {reason}'
        self.notify_status(message)
