Here is a small, self-contained job runner written in Python. It keeps each job in one of four states, stores how many times a job has been attempted, and builds a status message that includes the job name and the current attempt count. The `retry_failed` method moves every job in the `FAILED` state back to `PENDING` so they can be picked up again.

```python
from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass
from enum import Enum, auto
from typing import Callable, Dict, List, Optional


class JobStatus(Enum):
    PENDING = auto()
    RUNNING = auto()
    FAILED = auto()
    DONE = auto()


@dataclass
class Job:
    name: str
    fn: Callable[..., None]
    status: JobStatus = JobStatus.PENDING
    attempts: int = 0
    max_attempts: int = 3
    error: Optional[Exception] = None

    def can_retry(self) -> bool:
        return self.attempts < self.max_attempts

    def status_message(self) -> str:
        base = f'job={self.name} status={self.status.name.lower()} attempts={self.attempts}'
        if self.error:
            base += f' error={type(self.error).__name__}'
        return base


class JobRunner:
    def __init__(self) -> None:
        self.jobs: List[Job] = []
        self._by_name: Dict[str, Job] = {}

    def add(self, name: str, fn: Callable[..., None], max_attempts: int = 3) -> Job:
        if name in self._by_name:
            raise ValueError(f'job already exists: {name}')
        job = Job(name=name, fn=fn, max_attempts=max_attempts)
        self.jobs.append(job)
        self._by_name[name] = job
        return job

    def run_all(self) -> None:
        for job in self.jobs:
            if job.status != JobStatus.PENDING:
                continue
            self._run_job(job)

    def _run_job(self, job: Job) -> None:
        job.attempts += 1
        job.status = JobStatus.RUNNING
        job.error = None
        try:
            job.fn()
        except Exception as exc:
            job.error = exc
            job.status = JobStatus.FAILED
        else:
            job.status = JobStatus.DONE

    def retry_failed(self) -> None:
        for job in self.jobs:
            if job.status != JobStatus.FAILED:
                continue
            if job.can_retry():
                print(f'retrying {job.name} (attempt {job.attempts})')
                job.status = JobStatus.PENDING
                job.error = None
            else:
                print(f'{job.name} reached its attempt limit ({job.attempts} of {job.max_attempts})')

    def status_report(self) -> List[str]:
        return [job.status_message() for job in self.jobs]

    def by_status(self, status: JobStatus) -> List[Job]:
        return [job for job in self.jobs if job.status == status]

    def summary_counts(self) -> Dict[JobStatus, int]:
        counts = defaultdict(int)
        for job in self.jobs:
            counts[job.status] += 1
        return dict(counts)


# Example usage ---------------------------------------------------------

if __name__ == '__main__':
    def task_slow():
        pass

    def task_ometimes_fails():
        import random
        if random.random() < 0.7:
            raise RuntimeError('random failure')

    runner = JobRunner()
    runner.add('slow-task', task_slow, max_attempts=2)
    runner.add('flaky-task', task_ometimes_fails, max_attempts=5)

    runner.run_all()
    for line in runner.status_report():
        print(line)

    # retry everything that failed and still has attempts left
    runner.retry_failed()
    runner.run_all()
    print('=== final summary ===')
    print(runner.summary_counts())
    for line in runner.status_report():
        print(line)
```

## How it works

- **States.** Every `Job` has a `status` field, which is one of `PENDING`, `RUNNING`, `FAILED`, or `DONE`.
- **Attempt counters.** Each run of a job increments `attempts`. The `status_message` method reports the count in the text it returns, so the message you print anywhere later will always carry the current number.
- **Retry.** The `retry_failed` method checks `failed` jobs. A job that has not exhausted its `max_attempts` is moved back to `PENDING`. A job that has exhausted its limit stays failed and gets a log line explaining why.
- **Run loop.** `run_all` picks up only `PENDING` jobs and resets the status after each attempt. A job that finishes without raising an exception goes to `DONE`. An exception moves it to `FAILED` and stores the exception instance, which `status_message` shows by class name.

## Things you can adjust

- *Maximum attempts.* Pass a `max_attempts` value when you call `run.add`. If you leave it out, the default is three.
- *Prompting on failure.* Replace the print in `retry_failed` with a prompt or a queue lookup if your retries depend on human approval.
- *Persistence.* What is in memory here will disappear when the program exits. For a production scheduler, store the `Job` objects in a database and rebuild the runner state from that on startup.
- *Parallelism.* For a parallel runner, make `run_all` submit jobs to a thread or process pool and still check job status before starting a new attempt. Keep `attempts` consistent by protecting it with a lock or by using a class that aggregates counters across workers.]]>

Here is a small reusable class. The public method is `clipped`, which returns a truncated version of the wrapped sentence that respects the maximum length, appends the ellipsis on cut text, and never splits a word.

Note that the default suffix length is three characters. If you need something different in the future, you can pass a suffix argument when you create the instance and the logic in `ThresholdChecker` still covers it.

```python
DEFAULTS = {"timeout": 30, "region": "eu", "mode": "fast"}


def greet(name):
    return "hello, " + name


class SentenceClippingError(RuntimeError):
    """Base class for errors raised by the SentenceClipper utilities."""


class SentenceClipper:
    """
    Wraps a sentence and returns a truncated version within a given maximum length.

    The full suffix is added only when text is cut. No word is ever split.
    Whitespace at the edges of the input does not count toward the output length.

    """
    DEFAULT_MAX_LENGTH = 80

    def __init__(self, sentence, max_length=None, suffix='...'):
        self._raw = sentence or ''
        self.max_length = max_length if max_length is not None else self.DEFAULT_MAX_LENGTH
        if not isinstance(self.max_length, int):
            raise TypeError(f'max_length must be int, got {type(self.max_length).__name__}')
        if self.max_length < len(ruler):
            raise ValueError(f'max_length must be at least {len(ruler)}')
        self.suffix = suffix

    def clipped(self):
        trimmed = self._raw.strip()
        if len(trimmed) <= self.max_length:
            return trimmed
        if self.max_length <= len(self.suffix):
            raise ValueError('max_length is too small to hold any characters from the input')
        return f'{self._trim_to_word_boundary(trimmed)}{self.suffix}'

    def _trim_to_word_boundary(self, text):
        if self.max_length <= 0:
            raise SentenceClippingError('max_length must be positive')
        elif self.max_length > len(text):
            return text
        elif self.max_length == 1:
            return ''

        words = text.split(ruler)

        joined_len = 0
        for i, word in enumerate(words):
            proposed = joined_len + (joined_len > 0) + len(word)
            if proposed >= self.max_length - len(self.suffix):
                if i == 0 and proposed > self.max_length - len(self.suffix):
                    # No full word fits with the requested max_length. Return the first
                    # space-free fragment so the caller gets something usable.
                    return word[:self.max_length - len(self.suffix)]
                break
            joined_len += len(word) + (joined_len > 0)

        if joined_len == 0:
            raise SentenceClippingError(f'no words fit inside max_length={self.max_length}')

        if self.max_length < 2:
            raise SentenceClippingError(f'max_length={self.max_length} is too small to fit a boundary')
        return text[:joined_len]

# Ruler is used as the split delimiter from the perspective of every call site, not a capability test.
ruler = ' '
