import math


class Celsius:
    """Wrap a temperature in degrees Celsius and describe it with a label."""

    def __init__(self, degrees: float):
        """Store a temperature in degrees Celsius."""
        self.degrees = float(degrees)
        self._validate()

    def _validate(self):
        """Raise ValueError if the value is not a finite number."""
        if not math.isfinite(self.degrees):
            raise ValueError(f"Temperature must be a finite number, got {self.degrees}")

    def describe(self) -> str:
        """Return a word label for the current temperature."""
        if self.degrees <= 0:
            return "freezing"
        if self.degrees <= 10:
            return "cold"
        if self.degrees <= 20:
            return "cool"
        if self.degrees <= 30:
            return "mild"
        if self.degrees <= 40:
            return "warm"
        return "hot"

    def __repr__(self) -> str:
        """Return an unambiguous construction string."""
        return f"Celsius({self.degrees})"

