import re
from calendar import monthrange
from datetime import date, timedelta


MONTHS = {
    "january": 1,
    "february": 2,
    "march": 3,
    "april": 4,
    "may": 5,
    "june": 6,
    "july": 7,
    "august": 8,
    "september": 9,
    "october": 10,
    "november": 11,
    "december": 12,
}

ORDINALS = {
    "first": 1,
    "second": 2,
    "third": 3,
    "fourth": 4,
    "fifth": 5,
    "sixth": 6,
    "seventh": 7,
    "eighth": 8,
    "ninth": 9,
    "tenth": 10,
    "eleventh": 11,
    "twelfth": 12,
    "last": -1,
}


TODAY = date.today()


def is_title_case(text):
    """Return True if the first word of *text* starts with an capital letter."""
    first = text.split()[0]
    return first[:1].isupper()


def month_len(year, month):
    return monthrange(year, month)[1]


def title_case_date(d):
    return f"{d:%B} {d.day}, {d.year}"


def resolve_keyword(word, year, month):
    if word in ORDINALS:
        day = ORDINALS[word]
        if day == -1:
            return month_len(year, month)
        return day
    if word == "today":
        return TODAY
    if word == "tomorrow":
        return TODAY + timedelta(days=1)
    if word == "yesterday":
        return TODAY - timedelta(days=1)
    return None


def slice_desc(desc):
    desc = desc.strip().lower()
    anchors = re.findall(r"\b(first|second|third|fourth|fifth|last|today|tomorrow|yesterday)\b", desc)
    return anchors if len(anchors) == 2 else []


def parse_range(desc):
    year = TODAY.year
    for m in MONTHS:
        if m in desc.lower():
            month = MONTHS[m]
            break
    else:
        raise ValueError("no month found")
    for token in slice_desc(desc):
        if token == "last":
            return title_case_date(date(year, month, month_len(year, month)))
    start_token, end_token = slice_desc(desc)
    start_day = ORDINALS[start_token]
    day_of_last = ORDINALS.get(end_token, None)
    if day_of_last is None:
        raise ValueError("invalid range description")
    day_to_int = lambda d: month_len(year, month) if d == -1 else d
    end_day = day_to_int(day_of_last)
    start_date = date(year, month, start_day)
    end_date = date(year, month, end_day)
    return title_case_date(start_date), title_case_date(end_date)


if __name__ == "__main__":
    print(parse_range("first to last day of March 2025"))
    print(parse_range("third to twelfth of July"))
