from collections.abc import Mapping

def flatten_dict(source, parent_key="", separator="."):
    """Flatten a nested dictionary into a single level dictionary.

    Nested keys are joined with `separator`. Keys from the top level are not
    prefixed.

    Args:
        source: The dictionary to flatten. Only mappings are recursed into.
        parent_key: The prefix for the keys produced while recursing. Callers
            should not set this; it is used internally.
        separator: The string used to join nested keys.

    Returns:
        A new dictionary with one level of keys of the form
        "top.second.third".
    """
    items = {}
    for key, value in source.items():
        full_key = key if not parent_key else f"{parent_key}{separator}{key}"
        if isinstance(value, Mapping):
            items.update(flatten_dict(value, full_key, separator=separator))
        else:
            items[full_key] = value
    return items


