from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class RoundResult:
    player_a: str
    player_b: str
    winner: str | None

    def __str__(self) -> str:
        if self.winner is None:
            return f"Tie: both picked {self.player_a}"
        return f"{self.winner} wins: {self.player_a} vs {self.player_b}"


class RockPaperScissors:
    """Single-round game with two players.

    Moves are defined by a one-step cycle, so each move beats exactly one other move.
    With more than three moves, the logic extends automatically if the cycle is
    written in the expected order.
    """

    _wins_against = {"rock": "scissors", "scissors": "paper", "paper": "rock"}

    def __init__(self, moves: tuple[str, ...] | None = None):
        self._moves = tuple(_key for _key in (moves or tuple(self._wins_against))) or ()

        # Validate that the cycle is complete. A move must have a designated target.
        missing_keys = self._wins_against.keys() - self._moves
        if missing_keys:
            missing = ", ".join(sorted(missing_keys))
            raise ValueError(f"beats mapping does not cover all declared moves: {missing}")

    @property
    def moves(self) -> tuple[str, ...]:
        return self._moves

    def _validate_move(self, move: str) -> None:
        if move not in self._wins_against:
            raise ValueError(f"Invalid move {move!r}. Choose from: {', '.join(self._wins_against)}")

    def play(self, player_a: str, player_b: str) -> RoundResult:
        """Return a RoundResult describing who won an individual round."""
        self._validate_move(player_a)
        self._validate_move(player_b)

        if player_a == player_b:
            return RoundResult(player_a, player_b, None)

        winner = player_a if self._wins_against[player_a] == player_b else player_b
        return RoundResult(player_a, player_b, winner)


if __name__ == "__main__":
    game = RockPaperScissors()
    print(RoundResult("rock", "paper", "paper"))
