def _format_date(d):
    month = d.strftime("%B")
    day = d.day
    year = d.year
    return f"{month} {day}, {year}"


def _last_day_in_month(year, month):
    return calendar.monthrange(year, month)[1]


def parse_date_range(description, reference_date=None):
    """Return the start and end of a date range described in *description*.

    The return value is a tuple of two readable strings.

    Recognized forms are:
        * "YYYY-MM-DD to YYYY-MM-DD"
        * "first to last day of month"
        * "current month"
        * A single ISO date, which is returned as both the start and end.

    The recognition is case-insensitive and ignores extra spaces.
    """
    description = " ".join(description.lower().strip().split())
    today = reference_date if reference_date is not None else date.today()

    if description in {"current month", "this month"}:
        start = date(today.year, today.month, 1)
        end = date(today.year, today.month, _last_day_in_month(today.year, today.month))
        return _format_date(start), _format_date(end)

    if description == "last month":
        year = today.year
        month = today.month - 1
        if month == 0:
            month = 12
            year -= 1
        start = date(year, month, 1)
        end = date(year, month, _last_day_in_month(year, month))
        return _format_date(start), _format_date(end)

    if description == "first to last day of month":
        start = date(today.year, today.month, 1)
        end = date(today.year, today.month, _last_day_in_month(today.year, today.month))
        return _format_date(start), _format_date(end)

    if "to" in description:
        left, right = [part.strip() for part in description.split("to", 1)]
        start = datetime.fromisoformat(left).date()
        end = datetime.fromisoformat(right).date()
        return _format_date(start), _format_date(end)

    try:
        single = datetime.fromisoformat(description).date()
    except ValueError:
        raise ValueError(f"unrecognised date range: {description}")
    return _format_date(single), _format_date(single)


