from __future__ import annotations

from collections.abc import Mapping


def flatten_dict(data: Mapping, parent_key: str = "", sep: str = ".") -> dict:
    """Return a flat dictionary with dot-separated keys.

    Nested dictionaries are flattened into top-level keys whose names are
    formed by joining the keys from each level with `sep`. Non-dict values are
    stored unchanged under their path key.

    Examples
    --------
    >>> flatten_dict({"a": {"b": 1}, "c": 2})
    {"a.b": 1, "c": 2}
    >>> flatten_dict({"x": {"y": {"z": "hello"}}})
    {"x.y.z": "hello"}
    """
    if not isinstance(data, Mapping):
        raise TypeError("input must be a dictionary-like object")

    flat = {}
    for key, value in data.items():
        new_key = f"{parent_key}{sep}{key}" if parent_key else str(key)
        if isinstance(value, Mapping):
            flat.update(flatten_dict(value, new_key, sep=sep))
        else:
            flat[new_key] = value
    return flat


