from __future__ import annotations

from collections.abc import Mapping
from typing import Any, Dict


def flatten_dict(source: Mapping[str, Any], separator: str = '.') -> Dict[str, Any]:
    """Return a flat dictionary whose keys are the dot-separated paths of *source*.

    Only values that are themselves mappings are recursed into.  All other values,
    including lists, are stored unchanged.

    Args:
        source: A nested dictionary. Keys are assumed to be strings.
        separator: The string inserted between levels of nesting.

    Returns:
        A new dictionary with one entry per leaf in *source*.
        The original dictionary is left unmodified.
    """
    flat: Dict[str, Any] = {}

    def _flatten(current: Mapping[str, Any], prefix: str = '') -> None:
        for key, value in current.items():
            # Build the output key.  At the root level there is no prefix.
            joined = f'{prefix}{separator}{key}' if prefix else key
            if isinstance(value, Mapping):
                _flatten(value, joined)
            else:
                flat[joined] = value

    _flatten(source)
    return flat


if __name__ == '__main__':
    nested = {
        'app': {
            'debug': False,
            'hosts': ['localhost', '127.0.0.1'],
            'db': {
                'engine': 'sqlite',
                'path': '/var/db/app.db',
                'pool': {'max_size': 10, 'timeout': 30},
            },
        },
        'region': '',
    }

    for path, value in flatten_dict(nested).items():
        print(f'{path}: {value}')


