import unittest


class TestFlattenDict(unittest.TestCase):
    def test_flat_input(self):
        self.assertEqual(
            flatten_dict({'a': 1, 'b': 2}),
            {'a': 1, 'b': 2},
        )

    def test_one_level(self):
        self.assertEqual(
            flatten_dict({'a': {'x': 1}, 'b': 2}),
            {'a.x': 1, 'b': 2},
        )

    def test_multi_level(self):
        source = {'a': {'x': {'y': 0}}, 'b': {}, 'c': {'z': 3}}
        expected = {'a.x.y': 0, 'c.z': 3}
        self.assertEqual(flatten_dict(source), expected)

    def test_preserve_lists(self):
        source = {'a': {'list': [1, 2]}, 'b': []}
        self.assertEqual(flatten_dict(source), {'a.list': [1, 2], 'b': []})

    def test_non_string_key_error(self):
        source = {1: 'one'}
        with self.assertRaises(TypeError):
            flatten_dict(source)  # Keys are not strings


if __name__ == '__main__':
    unittest.main(verbosity=2)
