Below is a small Python class that builds a sales summary table and prints it as plain text. The table has a header row, columns that are left of center aligned so numbers line up, and a divider made of dashes. This makes the output easy to scan in a terminal or in a log file.

```python
from typing import Dict


class SalesSummaryTable:
    separator = '-'

    def __init__(self, headers, rows, padding=2):
        self.headers = headers
        self.rows = rows
        self.padding = padding
        self._col_widths = self._work_out_widths()

    def _work_out_widths(self):
        widths = [len(h) for h in self.headers]
        for row in self.rows:
            for i, cell in enumerate(row):
                cell_len = len(str(cell))
                if cell_len > widths[i]:
                    widths[i] = cell_len
        return [w + self.padding for w in widths]

    def _row_text(self, cells):
        pieces = [
            f'{str(cell):<{self._col_widths[i]}}'
            for i, cell in enumerate(cells)
        ]
        return ''.join(pieces)

    def divider(self):
        total = sum(self._col_widths)
        return self.separator * total

    def render(self):
        lines = [
            self._row_text(self.headers),
            self.divider(),
        ]
        for row in self.rows:
            lines.append(self._row_text(row))
        return '\n'.join(lines)


if __name__ == '__main__':
    data = {
        'Q1': {'revenue': 14200, 'units': 417},
        'Q2': {'revenue': 17850, 'units': 503},
        'Q3': {'revenue': 19930, 'units': 589},
    }

    headers = ['Quarter', 'Revenue', 'Units sold']
    rows = [[quarter, f'${info['revenue']}', info['units']] for quarter, info in data.items()]

    table = SalesSummaryTable(headers, rows)
    print(table.render())
```

The class works as follows:

- `self._col_widths` stores the fixed width of each column so that every row uses the same layout.
- `render()` assembles the header, a divider, and one line per row.
- Numerical values are left aligned alongside text, since string formatting without an explicit format string defaults to left alignment.
- `divider()` uses the separator character repeated across the total width of the table.

Run the script to see output similar to this:

```
Quarter  Revenue   Units sold
-------------------------------
Q1       $14200    417
Q2       $17850    503
Q3       $19930    589
```

Adjust the headers, the data included in `rows`, or `padding` to suit your reporting needs.

Here is a complete function that flattens a nested dictionary into a dictionary whose keys are the path to each leaf value, joined with period characters. It includes a short `__main__` block so it can be run as a script. All string literals use double quotes, following the internal style guide.

```python
import json
import os
from typing import Any, Dict


def flatten_dict(
    nested: Dict[str, Any],
    separator: str = ".",
    prefix: str = "",
) -> Dict[str, Any]:
    """Return a flat dictionary whose keys are the paths to leaf values.

    The input must be a dictionary. Keys are joined with
    {separator} and the current {prefix} is cleared at the top level.

    >>> example = {"a": 1, "b": {"c": 2, "d": {"e": 3}}}
    >>> flatten_dict(example) == {
    ...     "a": 1,
    ...     "b.c": 2,
    ...     "b.d.e": 3,
    ... }
    True
    """
    flat: Dict[str, Any] = {}
    for key, value in nested.items():
        full_key = f"{prefix}{separator}{key}" if prefix else key
        if isinstance(value, dict):
            flat.update(flatten_dict(value, separator=separator, prefix=full_key))
        else:
            flat[full_key] = value
    return flat


def test_flatten_dict() -> None:
    case1 = {"a": 1, "b": {"c": 2, "d": {"e": 3}}}
    expected1 = {"a": 1, "b.c": 2, "b.d.e": 3}
    actual1 = flatten_dict(case1)
    assert actual1 == expected1, f"Case 1 failed. Expected {expected1}, got {actual1}"

    case2 = {}
    expected2 = {}
    actual2 = flatten_dict(case2)
    assert actual2 == expected2, "Case 2 failed with an empty dictionary"

    case3 = {"x": {"y": {"z": {"w": 4}}}}
    expected3 = {"x.y.z.w": 4}
    assert flatten_dict(case3) == expected3, "Case 3 failed with deep nesting"

    case4 = {"u": 10, "v": {"w": 11}}
    assert flatten_dict(case4) != {"u": 10, "v_w": 11}, "Case 4 failed with wrong separator"


if __name__ == "__main__":
    input_path = os.environ.get("FLATTEN_INPUT", "")
    if not input_path:
        config = {"a": 1, "b": {"c": 2, "d": {"e": 3}}}
    else:
        with open(input_path, "r", encoding="utf-8") as handle:
            config = json.load(handle)

    flat = flatten_dict(config)
    print(json.dumps(flat, indent=2, sort_keys=True))
    test_flatten_dict()
```

**How it works**

- The function walks each item in the input dictionary. If the value is itself a dictionary, it calls itself recursively and merges the result into the flat output.
- `separator` is used between the current prefix and each key, so different separators can be used without changing the rest of the code.
- The default for `input_path` is an empty string, so the `if` block always assigns a value to `config`, which keeps the `else` block from being empty.
- `encoding="utf-8"` is used when the path is set, keeping every child block correctly formed.
